import {safeUrl,escapeHTML as e,daysUntil,effectiveStatus,sampleStatus,filterJobs,publicJobs,QUALIFICATIONS} from './utils.mjs';
import {adSenseReady,adsterraConfigured,adsterraReady,advertisingReady,bannerReady,renderBannerPlacement,monitorBannerFill,renderAdPlacement,startAdUnits,readAdvertisingConsent,openAdvertisingChoices,closeAdvertisingChoices,chooseAdvertising,resolveAdvertisingConfig} from './ads.mjs?v=ads-verified-only-20261031';

const PAGE= document.body.dataset.page || 'home';
const h=(s)=>e(s); const app=document.getElementById('app');
const NAV=[['Home','/'],['Latest Jobs','/latest-jobs/'],['Auto Notices','/auto-recruitment-notices/'],['Central','/central-government-jobs/'],['States','/state-government-jobs/'],['AP Jobs','/andhra-pradesh-jobs/'],['Telangana','/telangana-jobs/'],['Railways','/railway-jobs/'],['Banking','/banking-jobs/'],['SSC','/ssc-recruitment/'],['UPSC','/upsc-recruitment/'],['Exam Hub','/upcoming-exams/'],['Exam Updates','/exam-updates/'],['All States','/states-directory/'],['Guides','/career-guides/'],['Official Sources','/official-sources/'],['Notice Desk','/recruitment-updates/']];
const TILES=[['🏛️','Central Government','/central-government-jobs/','Discover central recruitment boards and exam pathways.'],['📍','All States & UTs','/states-directory/','Navigate all 28 states and 8 union territories.'],['🌾','Andhra Pradesh','/andhra-pradesh-jobs/','Locate AP commission recruitment resources.'],['🌿','Telangana','/telangana-jobs/','Browse Telangana categories and source guidance.'],['🚆','Railway Jobs','/railway-jobs/','Explore RRB sources and railway paths.'],['🏦','Banking Jobs','/banking-jobs/','Find IBPS and banking careers websites.'],['📋','SSC Recruitment','/ssc-recruitment/','Staff Selection Commission information.'],['🎓','UPSC Recruitment','/upsc-recruitment/','Civil services and other UPSC pathways.'],['🛡️','Police & Defence','/police-defence-jobs/','Police, army and defence information.'],['📚','Teaching Jobs','/teaching-jobs/','Explore teaching eligibility and recruitment.'],['🎯','Qualification-wise','/qualification-wise-jobs/','Find options by your education level.'],['🔎','Advanced Search','/job-search/','Filter independently verified records and try optional training mode.']];
const CATS={latest:{title:'Latest Government Jobs',desc:'Browse only independently reviewed listings; only verified government notices appear in the live listing. Try sample search separately in training mode.',prefill:{}},central:{title:'Central Government Jobs',desc:'Explore central government recruitment pathways and source websites. Only notices checked against actual advertisements appear here.',prefill:{type:'Central'}},state:{title:'State Government Jobs',desc:'Browse state-level pathways and filter verified records by state, education and department.',prefill:{type:'State'}},ap:{title:'Andhra Pradesh Government Jobs',desc:'For APPSC and other Andhra Pradesh recruitment, check the respective authorities directly. Verify specific eligibility and deadlines for each listed notice.',prefill:{state:'Andhra Pradesh'}},telangana:{title:'Telangana Government Jobs',desc:'Explore Telangana recruitment sources and categories. Confirm commission domains through a government directory before following any notice.',prefill:{state:'Telangana'}},railway:{title:'Railway Recruitment',desc:'Railway recruitment is published by relevant RRB/RRC authorities. This page only displays separately verified notices, not guessed openings.',prefill:{category:'Railway'}},banking:{title:'Banking Jobs',desc:'Use IBPS and bank career websites to confirm notices. Confirmed vacancies appear below when available.',prefill:{category:'Banking'}},ssc:{title:'SSC Recruitment',desc:'The Staff Selection Commission publishes recruitment information on its own website. Verify the latest SSC advertisements directly before applying.',prefill:{category:'SSC'}},upsc:{title:'UPSC Recruitment',desc:'Consult UPSC announcements and official examination calendars. This portal is independent and not endorsed by UPSC.',prefill:{category:'UPSC'}},defence:{title:'Police & Defence Jobs',desc:'Police boards and defence organizations each publish their own rules. Never rely on unverified social-media notices.',prefill:{category:'Police & Defence'}},teaching:{title:'Teaching Jobs',desc:'Teaching recruitment and eligibility exams are different: verify the actual role and its requirements before applying.',prefill:{category:'Teaching'}},search:{title:'Search & Filter Jobs',desc:'Find independently verified vacancies by title, region, qualification, organization, deadline and status. To explore fictional examples, use explicit training mode.',prefill:{}}};
let jobs=[],sources=[],pages={},examUpdatesData=[],regions={states:[],unionTerritories:[]},noticeWatch=[],autoNotices={version:1,notices:[]},adsConfig={enabled:false,provider:'none',publisherId:'',slots:{content:''}};
// Fictional records stay available only when an explicit ?demo=1 mode is selected.
const DEMO_MODE=new URLSearchParams(location.search).get('demo')==='1';
function viewJobs(){return publicJobs(jobs,DEMO_MODE)}
let saved=new Set(safeStorage('jp_saved',[]));
function safeStorage(key,fallback){try{const v=JSON.parse(localStorage.getItem(key));return Array.isArray(v)?v:fallback}catch{return fallback}}
function remember(){try{localStorage.setItem('jp_saved',JSON.stringify([...saved]))}catch{toast('Storage unavailable; saved jobs are session-only.')}}
function setTheme(theme){document.documentElement.dataset.theme=theme;try{localStorage.setItem('jp_theme',theme)}catch{} const b=document.querySelector('[data-theme-toggle]');if(b){b.setAttribute('aria-label',theme==='dark'?'Switch to light mode':'Switch to dark mode');b.textContent=theme==='dark'?'☀️':'🌙'}}
function toast(s){let el=document.getElementById('toast');if(!el){el=document.createElement('div');el.id='toast';el.setAttribute('role','status');el.className='app-toast';document.body.append(el)}el.textContent=s;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.remove(),3200)}
function header(){return `<header class="site-header"><div class="wrap header-main"><a class="brand" href="/" aria-label="JobPath India home"><img src="/assets/icons/logo.svg" width="42" height="42" alt=""><span>JOBPATH INDIA<small>YOUR CAREER. CLEARER PATHS.</small></span></a><div class="header-actions"><a class="btn btn-secondary header-desktop" href="/saved-jobs/">♡ Saved <span id="saved-count">${saved.size}</span></a><a class="btn btn-primary header-desktop" href="/job-search/">Search Jobs</a><button class="icon-btn" type="button" data-theme-toggle aria-label="Switch color theme">🌙</button><button class="icon-btn menu-button" type="button" data-menu aria-label="Open navigation menu" aria-expanded="false" aria-controls="primary-nav">☰</button></div></div><div class="nav-rail" id="primary-nav"><nav class="wrap nav-wrap" aria-label="Main navigation">${NAV.map(([title,url])=>`<a href="${url}" ${location.pathname===url?`aria-current="page"`:''}>${h(title)}</a>`).join('')}</nav></div></header><div class="info-banner"><div class="wrap"><strong>Independent government recruitment information · Source-first directory.</strong> ${jobs.some(j=>j.verified&&!j.isDemo)?'Check each notice and last verification date; demonstration cards are explicitly labeled.':DEMO_MODE?'Training mode: fictional sample records only — not current vacancies.':'Use the original notification and the last-checked date for each listed recruitment.'} <a href="/disclaimer/">Read disclaimer</a>.</div></div>`}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-cols"><div><a class="brand" href="/"><img src="/assets/icons/logo.svg" alt="" width="42" height="42"><span>JOBPATH INDIA<small>INDEPENDENT RECRUITMENT INFORMATION</small></span></a><p style="margin-top:18px;max-width:340px">Built to help people navigate recruitment information responsibly. This is not a government website.</p></div><div><h3>Explore</h3>${[['Latest Jobs','/latest-jobs/'],['Official Sources','/official-sources/'],['Qualifications','/qualification-wise-jobs/'],['Admit Cards','/admit-cards/'],['Exam Results','/exam-results/'],['Syllabus','/exam-syllabus/'],['Important Dates','/important-dates/'],['Exam Calendar','/exam-calendar/'],['All States','/states-directory/']].map(([s,u])=>`<a href="${u}">${h(s)}</a>`).join('')}</div><div><h3>Information</h3>${[['About','/about/'],['Contact','/contact/'],['Privacy','/privacy-policy/'],['Terms','/terms/'],['Disclaimer','/disclaimer/'],['Local Alerts','/job-alerts/'],['Editorial Policy','/editorial-policy/'],['FAQs','/faq/'],['Application Guide','/application-guide/']].map(([s,u])=>`<a href="${u}">${h(s)}</a>`).join('')}</div></div>${adsterraReady(adsConfig)?'<button type="button" class="ad-footer-choice" data-ad-choices>Advertising choices</button>':''}<button type="button" class="analytics-choice-trigger" data-analytics-choices>Analytics choices</button><div class="footer-bottom">© ${new Date().getFullYear()} JobPath India · Independent informational project · No government affiliation · No application fees are collected on this site.</div></div></footer>`}
function bread(name){return `<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a> / ${h(name)}</nav>`}
function intro(title,desc,eyebrow='Information hub'){return `<section class="page-intro">${bread(title)}<div class="eyebrow">${h(eyebrow)}</div><h1>${h(title)}</h1><p class="lead">${h(desc)}</p></section>`}
function sectionHeader(name,sub='',url=null){return `<div class="section-head"><div><h2>${h(name)}</h2>${sub?`<p>${h(sub)}</p>`:''}</div>${url?`<a href="${url}">View all →</a>`:''}</div>`}
function chips(){return QUALIFICATIONS.map(q=>`<a class="chip" href="/job-search/?qualification=${encodeURIComponent(q)}">${h(q)} →</a>`).join('')}
function tile(x){return `<a class="tile" href="${x[2]}"><div class="tile-icon" aria-hidden="true">${x[0]}</div><h3>${h(x[1])} ↗</h3><p>${h(x[3])}</p></a>`}
// Keep advertising in the designated top slot, not repeated inside job lists.
function ad(){return ''}
function topAd(){
 if(!['home','latest','central','railway','banking'].includes(PAGE))return '';
 // Only consented visitors see the approved host-bound Adsterra native unit.
 // We never load tracking-based ads in the absence of visitor authorization.
 if(adsterraReady(adsConfig)&&readAdvertisingConsent()!=='allow')return '';
 const html=renderAdPlacement(adsConfig,'top');
 return html?'<div class="top-ad-region">'+html+'</div>':'';
}
// Small, in-flow choice after the hero, not a full-width ad consent interruption.
// Declining or ignoring this choice never stops job information from working.
function siteBanner(location){return renderBannerPlacement(adsConfig,location,globalThis.location?.hostname||'',readAdvertisingConsent())}
function adQuickAccess(){
 if(PAGE!=='home'||!adsterraReady(adsConfig)||readAdvertisingConsent()!==null||
    globalThis.window?.navigator?.globalPrivacyControl===true)return '';
 return '<aside class="ad-quick-choice" aria-label="Optional sponsored advertising">'+
 '<div><strong>Optional sponsored ads</strong><p>Adsterra may show unrelated or dating-style adverts until provider restrictions are confirmed. Ads use device data. <a href="/privacy-policy/">Privacy details</a>.</p></div>'+
 '<div class="ad-quick-actions"><button type="button" class="btn btn-primary btn-sm" data-ad-choice="allow">Show sponsored ads</button>'+
 '<button type="button" class="btn btn-secondary btn-sm" data-ad-choice="deny">Keep ads hidden</button></div></aside>';
}
// Extra approved ad unit IDs are required. Hide unused slots completely.
function futureAdPosition(id){return '<div class="ad-ready-position" data-jobpath-future-ad="'+id+'" hidden aria-hidden="true"></div>'}
function sourceCard(x){const link=safeUrl(x.url);return `<div class="source-card" data-source-category="${h(x.category)}" data-source-name="${h(x.name.toLowerCase())}"><div class="label-scope">${h(x.category)}</div><h3>${h(x.name)}</h3><p>${h(x.note)}</p><p class="tiny muted">${x.lastChecked?'Domain/notice checked: '+h(x.lastChecked):'Reference directory entry; recheck before use'}</p>${link?`<a href="${h(link)}" target="_blank" rel="noopener noreferrer">Visit organization website ↗</a>`:`<span class="muted tiny">Official domain not confirmed — no link shown</span>`}</div>`}
function sourcesTeaser(){return `<section class="section">${sectionHeader('Start with the official source','Checked sources include CWC, SSC, APPSC, RRB, and IBPS; always revisit the latest official notice.','/official-sources/')}<div class="grid">${sources.slice(0,3).map(sourceCard).join('')}</div></section>`}
function statusLabel(job){const st=job.isDemo?sampleStatus(job):effectiveStatus(job);return `<span class="tag ${st==='closed'?'closed':job.isDemo?'demo':''}">${job.isDemo?'DEMO · ':''}${h(st.toUpperCase())}</span>`}
function deadlineLabel(job){const days=daysUntil(job.lastDate);const kind=job.isDemo?'Sample deadline':'Deadline';if(days===null)return 'No date supplied';if(days<0)return `${kind} passed ${Math.abs(days)} day${Math.abs(days)===1?'':'s'} ago`;if(days===0)return `${kind}: today`;return `${kind} in ${days} day${days===1?'':'s'}`}
function jobCard(j){const real=j.verified&&!j.isDemo;const official=safeUrl(j.applicationUrl);return `<article class="job-card"><div class="tags"><span class="tag ${real?'':'demo'}">${real?'SOURCE-VERIFIED RECORD':'FICTIONAL EXAMPLE'}</span>${statusLabel(j)}</div><div><div class="org">${h(j.organization)}</div><h3><a href="/job/?id=${encodeURIComponent(j.id)}">${h(j.title)}</a></h3></div><div class="job-meta"><span>📍 ${h(j.state)}</span><span>🎓 ${h(j.qualification)}</span><span>🏛 ${h(j.type)}</span><span>🗓 ${h(j.lastDate||'Not specified')}</span></div><p class="tiny muted">${h(deadlineLabel(j))} · ${real?'Last verified: '+h(j.lastVerifiedDate||'unknown'):'No application available'}</p><div class="job-actions"><a class="btn btn-primary btn-sm" href="/job/?id=${encodeURIComponent(j.id)}">${real?'View details':'View example'}</a>${real&&official&&effectiveStatus(j)!=='closed'?`<a class="btn btn-secondary btn-sm" href="${h(official)}" target="_blank" rel="noopener noreferrer">Official apply ↗</a>`:''}<button type="button" class="btn btn-ghost btn-sm" data-save="${h(j.id)}" aria-label="${saved.has(j.id)?'Remove from saved':'Save'} ${h(j.title)}">${saved.has(j.id)?'♥ Saved':'♡ Save'}</button></div></article>`}
function examTeaser(){const n=examUpdatesData[0];if(!n)return '';return `<section class="section">${sectionHeader('SSC 2026 examination date corrigendum','Reader-provided schedule update · Source review pending · Not a recruitment opening','/exam-updates/')}<div class="panel"><div class="tags"><span class="tag">EXAM SCHEDULE</span><span class="tag demo">VERIFY ON SSC</span></div><h3 style="margin-top:12px">${h(n.title)}</h3><p>${h(n.caveat)}</p><div class="action-row"><a class="btn btn-primary" href="/exam-updates/">Read proposed dates</a><a class="btn btn-secondary" href="https://ssc.gov.in/" target="_blank" rel="noopener noreferrer">SSC website ↗</a></div></div></section>`}
function examUpdatesPage(){
 const n=examUpdatesData[0];
 if(!n)return intro('Exam update unavailable','The notice data could not be loaded.');
 const date=d=>new Date(`${d}T00:00:00Z`).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'});
 // The notice is a proposed exam calendar correction, not a job advertisement.
 // Use semantic, vertically stacked exam cards instead of a table that scrolls sideways on phones.
 const cards=n.revisedProposedExams.map((exam,index)=>{
   const windows=exam.windows.map((window,w)=>`<li><span class="exam-window-number">${exam.windows.length>1?`Window ${w+1}`:'Proposed examination period'}</span><div class="exam-window-dates"><time datetime="${h(window.start)}">${h(date(window.start))}</time><span aria-hidden="true"> – </span><time datetime="${h(window.end)}">${h(date(window.end))}</time></div></li>`).join('');
   return `<section class="exam-schedule-card" aria-labelledby="ssc-exam-${index}"><div class="tags"><span class="tag">PROPOSED · NOT FINAL</span><span class="tag demo">VERIFY ON SSC</span></div><h3 id="ssc-exam-${index}">${h(exam.name)}</h3><p class="exam-mode"><strong>Tier / mode:</strong> ${h(exam.tier)}</p><ul class="exam-windows">${windows}</ul></section>`;
 }).join('');
 return `${intro('SSC 2026: Revised proposed exam dates','Corrigendum dated 26 October 2026 relating to an Important Notice of 1 October 2026. This is an examination schedule update, not an invitation to apply.','Source document summary')}
 <div class="notice warn"><strong>Source review pending.</strong> This transcription uses screenshots supplied by a reader. The official SSC notice board confirms this notice title; the full PDF itself has not been compared. These dates are <strong>proposed</strong>, not guaranteed final. Confirm SSC's latest notice before travel or exam planning.</div>
 <article class="panel content-block"><div class="tags"><span class="tag">SSC · EXAM UPDATE</span><span class="tag demo">NOT A JOB OPENING</span></div><h2>Revised proposed examination dates</h2><div class="exam-schedule">${cards}</div><p class="muted tiny exam-caption">Both Junior Engineer date windows are shown separately, exactly as stated in the supplied corrigendum.</p>
 <h2>Notice details</h2><dl class="notice-data"><div><dt>Organization</dt><dd>${h(n.organization)}</dd></div><div><dt>Reference</dt><dd>${h(n.reference)}</dd></div><div><dt>Notice heading</dt><dd>${h(n.noticeHeading)}</dd></div><div><dt>Signed date</dt><dd>${h(date(n.noticeSignedDate))}</dd></div><div><dt>Document source</dt><dd>${h(n.source)}</dd></div><div><dt>Verification status</dt><dd>${h(n.sourceStatus)}</dd></div></dl>
 <div class="notice warn"><strong>Not a fresh vacancy notification.</strong> This document provides no vacancy count, application deadline, eligibility, fee, or application URL. Do not treat it as an active recruitment listing.</div>
 <div class="action-row"><a class="btn btn-primary" href="https://ssc.gov.in/" target="_blank" rel="noopener noreferrer">Check latest SSC notices ↗</a><button class="btn btn-secondary" type="button" data-print>Print summary</button><button class="btn btn-secondary" type="button" data-copy-link>Copy page link</button></div>
 <h2>Reader-supplied notice images</h2><p class="muted">Images supplied for transcription, not an official hosted document link. Refer to the Commission's latest notices for binding instructions.</p><div class="notice-images">${n.imageFiles.map((p,i)=>`<figure><a href="${h(p)}" target="_blank" rel="noopener noreferrer"><img loading="lazy" src="${h(p)}" alt="Supplied SSC corrigendum screenshot page ${i+1}" width="700"></a><figcaption>Provided image · page ${i+1}</figcaption></figure>`).join('')}</div></article>`;
}

function autoNoticesSection(limit=6){
 const items=Array.isArray(autoNotices?.notices)?autoNotices.notices.slice(0,limit):[];
 const cards=items.map(n=>{
   const official=safeUrl(n.noticeUrl);
   if(!official||n.verificationStatus!=='automatically_detected_unverified')return '';
   return `<article class="source-card"><div class="tags"><span class="tag demo">AUTO-DETECTED · UNVERIFIED</span></div><h3>${h(n.title)}</h3><p>${h(n.organization)}</p><p class="tiny muted">Detected ${h(n.detectedDate)} · Application window not checked</p><a href="${h(official)}" target="_blank" rel="noopener noreferrer">Read original source notice ↗</a></article>`;
 }).filter(Boolean);
 return `<section class="section" id="auto-notices">${sectionHeader('Automatically detected recruitment notices','Official-website links found by daily monitoring. NOT verified jobs; no application status, eligibility or deadline is confirmed.','/auto-recruitment-notices/')}<div class="notice warn"><strong>These are NOT confirmed open vacancies.</strong> Check the current official notice and corrigenda before using any information or applying.</div>${cards.length?`<div class="grid">${cards.join('')}</div>`:'<div class="panel"><p>No new qualifying official notice links detected yet. Some government sites block automated checks; try the source directory.</p><a href="/official-sources/">Open official source directory ↗</a></div>'}</section>`;
}
function autoNoticesPage(){return `${intro('Automatically Detected Recruitment Notices','Daily checks may publish official recruitment notice links automatically, without manual approval. They are not verified vacancies or application invitations.','Automatic source watch')}${autoNoticesSection(60)}${sourcesTeaser()}`}

function home(){const realJobs=publicJobs(jobs,false);return `${siteBanner("responsive")}<section class="hero"><div><div class="eyebrow">GOVERNMENT CAREER INFORMATION · INDIA</div><h1>Explore opportunities with a clearer path.</h1><p class="lead">A modern portal for job pathways, trustworthy source discovery, exam guides and smart search. We're building an independent information resource — not publishing unverified openings.</p><div class="hero-actions"><a href="/job-search/" class="btn btn-secondary">🔎 Search verified jobs</a><a href="/official-sources/" class="btn btn-primary">Browse Official Sources ↗</a></div><p class="tiny" style="margin-top:19px;color:#cdeaff">${realJobs.length?'Browse the independently reviewed listings below and confirm each notice at its source.':'See the records reviewed on 28 October 2026 and check latest issuer updates before applying.'}</p></div><div class="hero-art" aria-hidden="true"><div class="art-row"><span class="art-icon">🔎</span><div><strong>Smart search</strong><div class="tiny">By location, qualification & more</div></div></div><div class="art-row"><span class="art-icon">🗂️</span><div><strong>Trusted source discovery</strong><div class="tiny">Recruiting organizations</div></div></div><div class="art-row"><span class="art-icon">♡</span><div><strong>Save for later</strong><div class="tiny">Stored in your browser</div></div></div></div></section>${adQuickAccess()}<div class="stats"><div class="stat"><strong>${sources.length}</strong><span>Source directory entries</span></div><div class="stat"><strong>${realJobs.length}</strong><span>Verified vacancy records</span></div><div class="stat"><strong>₹0</strong><span>Fees charged by this portal</span></div></div><aside class="career-highlight" aria-label="Government career resources"><div class="career-highlight-copy"><span class="career-highlight-tag">CAREER RESOURCES · NO THIRD-PARTY ADS</span><strong>Looking for genuine recruitment information?</strong><p>Explore source-checked opportunities and the official recruitment directory. No dating, gambling or unrelated promotions.</p></div><div class="career-highlight-links"><a class="btn btn-primary btn-sm" href="/latest-jobs/">Explore latest jobs ↗</a><a class="btn btn-secondary btn-sm" href="/official-sources/">Official sources</a></div></aside>${examTeaser()}${autoNoticesSection(3)}<section class="section">${sectionHeader('Explore by career path','Go directly to the information relevant to you.')}<div class="grid">${TILES.map(tile).join('')}</div></section>${siteBanner('rectangle')}<section class="section">${sectionHeader('Latest reviewed vacancies',realJobs.length?'Only independently checked entries appear here. Confirm each official PDF and its date.':'Browse recruitment records checked against official issuing authorities, and check all later corrigenda.','/latest-jobs/')} ${realJobs.length?`<div class="grid">${realJobs.slice(0,3).map(jobCard).join('')}</div>`:`<div class="panel" style="padding:24px"><h3>No verified vacancies published</h3><p>For current openings, check the recruiting organization directly. We list useful source websites below, but links have not been rechecked live.</p><div class="action-row"><a class="btn btn-primary" href="/official-sources/">Browse recruitment sources ↗</a><a class="btn btn-secondary" href="/job-search/?demo=1">Try sample search (demo)</a></div></div>`}</section><section class="section">${sectionHeader('Find jobs by education','These shortcuts preselect an education filter.')}<div class="chips">${chips()}</div></section>${sourcesTeaser()}<section class="section">${sectionHeader('Examination resources','Verify dates and documents directly with recruiting authorities.')}<div class="grid">${[['🪪','Admit cards','/admit-cards/','Download only from official candidate portals.'],['✅','Exam results','/exam-results/','Use official result and merit list links.'],['📆','Important dates','/important-dates/','Practice with an example deadline timeline.']].map(tile).join('')}</div></section>${topAd()}`}
function options(key,items,val){return `<option value="">All ${h(key)}</option>${items.filter(Boolean).sort((a,b)=>a.localeCompare(b)).map(x=>`<option value="${h(x)}" ${x===val?'selected':''}>${h(x)}</option>`).join('')}`}
function selectField(key,label,items,filters){return `<div class="field"><label for="filter-${key}">${h(label)}</label><select id="filter-${key}" name="${key}">${options(label.toLowerCase(),items,filters[key])}</select></div>`}
function queryFilters(preset={}){const qs=new URLSearchParams(location.search);const filters={...preset};for(const key of ['q','state','type','qualification','department','organization','category','status','deadline','sort'])if(qs.has(key))filters[key]=qs.get(key)||'';return filters}
function filterPanel(filters){const unique=key=>[...new Set(viewJobs().map(j=>j[key]))];return `<aside class="filter-panel"><h2 style="font-size:1.2rem">Refine results</h2><form id="search-form" role="search"><div class="filter-fields"><div class="field"><label for="filter-q">Search title or keyword</label><input autocomplete="off" id="filter-q" name="q" value="${h(filters.q||'')}" placeholder="e.g. Assistant, Railway"><ul id="search-suggestions" class="suggestions" aria-label="Search suggestions"></ul></div>${selectField('state','State',unique('state'),filters)}${selectField('type','Government type',unique('type'),filters)}${selectField('qualification','Qualification',QUALIFICATIONS,filters)}${selectField('department','Department',unique('department'),filters)}${selectField('organization','Organization',unique('organization'),filters)}${selectField('category','Job category',unique('category'),filters)}<div class="field"><label for="filter-deadline">Application deadline</label><select id="filter-deadline" name="deadline"><option value="">Any deadline</option>${[['7','Next 7 days'],['30','Next 30 days'],['future','Not expired']].map(([v,t])=>`<option value="${v}" ${filters.deadline===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="filter-status">${DEMO_MODE?'Example status':'Status'}</label><select id="filter-status" name="status"><option value="">All statuses</option>${[['open','Open'],['upcoming','Upcoming'],['closed','Closed']].map(([v,t])=>`<option value="${v}" ${filters.status===v?'selected':''}>${t}</option>`).join('')}</select></div></div><button type="button" class="btn btn-secondary" data-clear-filters>Clear filters</button></form></aside>`}
function renderResults(){const f=new FormData(document.getElementById('search-form'));const filters=Object.fromEntries(f.entries());filters.sort=document.getElementById('filter-sort')?.value||'newest';const filtered=filterJobs(viewJobs(),filters);const place=document.getElementById('results-list');if(!place)return;place.innerHTML=filtered.length?filtered.map(jobCard).join(''):`<div class="empty" style="grid-column:1/-1"><h3>${!DEMO_MODE&&!viewJobs().length?'No independently verified vacancy records yet':'No matching records'}</h3><p>${!DEMO_MODE&&!viewJobs().length?'This website has not independently checked any current vacancies. For real notices, use the recruitment authorities below.':'Try a broader filter or explore the source directory.'}</p><a href="/official-sources/" class="btn btn-primary">Browse source websites</a>${!DEMO_MODE?`<a href="/job-search/?demo=1" class="btn btn-secondary">Try fictional search examples</a>`:''}</div>`;document.getElementById('result-count').textContent=`${filtered.length} result${filtered.length===1?'':'s'} ${DEMO_MODE?' (fictional training records included)':' (verified records only)'}`;const path=location.pathname;const u=new URL(location.href);for(const key of ['q','state','type','qualification','department','organization','category','status','deadline','sort'])u.searchParams.delete(key);for(const [k,v] of Object.entries(filters))if(v&&!(k==='sort'&&v==='newest'))u.searchParams.set(k,v);history.replaceState({},'',path+(u.search||''));const term=filters.q?.trim().toLowerCase();const suggestions=document.getElementById('search-suggestions');if(suggestions){suggestions.innerHTML=term?viewJobs().filter(j=>j.title.toLowerCase().includes(term)).slice(0,4).map(j=>`<li><a href="/job/?id=${encodeURIComponent(j.id)}">${h(j.title)}</a></li>`).join(''):''}}
function listing(page){const conf=CATS[page];const f=queryFilters(conf.prefill);return `${intro(conf.title,conf.desc,'Browse & filter')}<div class="notice warn"><strong>${DEMO_MODE?'TRAINING MODE — fictional examples':'Independent recruitment information'}</strong> ${DEMO_MODE?'All sample organizations, dates and roles are invented. Do not apply based on these records.':'Source-checked job records are shown below. An expired date automatically marks a record closed; recheck each issuer before applying.'} <a href="/official-sources/">Visit recruitment source directory</a>.</div><div class="two-column">${filterPanel(f)}<section aria-label="Job search results"><div class="results-head"><strong id="result-count">Loading available records...</strong><div class="field" style="margin:0;min-width:195px"><label for="filter-sort">Sort results</label><select id="filter-sort"><option value="newest" ${f.sort==='newest'?'selected':''}>Most recently added</option><option value="deadline" ${f.sort==='deadline'?'selected':''}>Nearest deadline</option><option value="title" ${f.sort==='title'?'selected':''}>Job title A–Z</option><option value="organization" ${f.sort==='organization'?'selected':''}>Organization A–Z</option></select></div></div><div class="results-list" id="results-list"></div><div class="section">${ad()}</div></section></div>${page==='latest'?autoNoticesSection(12):''}${sourcesTeaser()}`}
function detail(){
 const id=new URLSearchParams(location.search).get('id');const j=jobs.find(x=>x.id===id);
 if(!j)return `${intro('Job record not found','This reference does not match a listing.')}<a href="/job-search/" class="btn btn-primary">Search listings</a>`;
 const demo=j.isDemo||!j.verified;
 const notification=demo?null:safeUrl(j.notificationUrl),application=demo?null:safeUrl(j.applicationUrl);
 const vals=[['Organization',j.organization],['Category',j.category],['Government type',j.type],['State',j.state],['Qualification',j.qualification],['Department',j.department],['Application start'+(demo?' (sample)':''),j.startDate||'Not provided'],['Application deadline'+(demo?' (sample)':''),j.lastDate||'Not provided'],['Notice publication date',j.publishedDate||'Not provided'],['Vacancies',j.vacancies??'Not provided'],['Age limits',j.minAge||j.maxAge?`${j.minAge||'Not specified'} – ${j.maxAge||'Not specified'}`:'Not provided'],['Pay scale',j.payScale||'Not provided'],['Application fees',j.fees||'Not provided'],['Selection process',j.selectionProcess||'Not provided'],['Source organization',j.sourceOrganization],['Last verified date',demo?'Never — fictional example':(j.lastVerifiedDate||'Not provided')]];
 const warning=demo?'<strong>NOT A REAL GOVERNMENT JOB.</strong> This is a fabricated test fixture for demonstrating website functionality. Do not apply, pay fees or share personal information on the basis of this example.':'<strong>Independent summary:</strong> Confirm the current notification, eligibility, corrigenda and application deadline directly on the recruiting organization’s site. This portal is not the recruiting authority.';
 const officialButtons=demo?'<a href="/official-sources/" class="btn btn-primary">Find actual official sources</a>':`${notification?`<a class="btn btn-secondary" href="${h(notification)}" target="_blank" rel="noopener noreferrer">Read official notification ↗</a>`:''}${application&&effectiveStatus(j)!=='closed'?`<a class="btn btn-primary" href="${h(application)}" target="_blank" rel="noopener noreferrer">Apply on official site ↗</a>`:''}`;
 return `${intro(j.title,demo?'Fictional test record. No job opening exists based on this listing.':'Recruitment information summary. Always defer to official notices.',demo?'Demonstration job detail':'Recruitment information')}<div class="notice warn">${warning}</div><div class="split"><article class="panel"><div class="tags">${statusLabel(j)}<span class="tag ${demo?'demo':''}">${demo?'DEMO ID: ':'RECORD ID: '}${h(j.id)}</span></div><h2 style="margin-top:20px">${demo?'Example listing information':'Listing information'}</h2><p>${h(j.description||'Refer to the official recruitment advertisement for full information.')}</p><table class="detail-table"><tbody>${vals.map(([k,v])=>`<tr><th scope="row">${h(k)}</th><td>${h(v)}</td></tr>`).join('')}</tbody></table><div class="action-row"><button class="btn btn-secondary" type="button" data-save="${h(j.id)}">${saved.has(j.id)?'♥ Saved':'♡ Save'}</button><button type="button" class="btn btn-secondary" data-copy-link>Copy link</button><button type="button" class="btn btn-secondary" data-share>Share</button><button type="button" class="btn btn-secondary" data-print>Print</button>${officialButtons}</div></article><aside><div class="panel"><h3>Application checklist</h3><ol class="checklist"><li>Find an actual notification on the recruiting organization's official website.</li><li>Confirm eligibility, age criteria and application dates.</li><li>Check vacancies, fees and selection rules from the PDF.</li><li>Use the official application link only.</li><li>Keep your application acknowledgment safely.</li></ol></div><div class="section">${ad()}</div></aside></div>`;
}
function savedPage(){const present=jobs.filter(x=>saved.has(x.id));return `${intro('Saved Jobs','Your saved listings are stored in this browser only. There is no online account or automatic alert delivery.','Local bookmarks')}<div class="notice">${jobs.some(j=>j.verified&&!j.isDemo)?'Demo cards remain fictional; review actual notices only at the official sources.':'Verified recruitment records are source-checked as of 28 October 2026. Demo records, if saved, are fictional training examples only.'}</div>${present.length?`<div class="grid">${present.map(jobCard).join('')}</div>`:`<div class="empty"><h2>No saved jobs yet</h2><p>Save a verified listing to find it again later in this browser.</p><a href="/job-search/" class="btn btn-primary">Browse examples</a></div>`}`}
function deadlinePage(){const upcoming=publicJobs(jobs,false).filter(j=>daysUntil(j.lastDate)>=0).sort((a,b)=>a.lastDate.localeCompare(b.lastDate));return `${intro('Important Application Dates','Only application dates independently checked against official notices appear here. For current deadlines consult the recruiting organization.','Date tracker')}<div class="notice warn">Dates shown below were reviewed on 28 October 2026. Confirm last-minute extensions or closures on the recruiting authority’s website.</div>${upcoming.length?`<div class="grid">${upcoming.map(jobCard).join('')}</div>`:`<div class="empty"><h2>No official deadlines published yet</h2><p>Review the recruiting organization's official notice for current deadlines and corrigenda.</p><a class="btn btn-primary" href="/official-sources/">Find source websites</a></div>`}`}
function qualificationPage(){return `${intro('Jobs by Qualification','Choose a qualification to prefill the search interface. Real openings must be checked on official sites.','Career pathways')}<div class="grid">${QUALIFICATIONS.map((q,i)=>tile([['🎒','📘','🔧','🧰','🎓','💻','📚','✨'][i],q,'/job-search/?qualification='+encodeURIComponent(q),'Browse independently verified listings by qualification; use demo mode separately.'])).join('')}</div>${sourcesTeaser()}`}
function officialSources(){return `${intro('Official Recruitment Source Directory','Use organization websites as your starting point for authentic notices. Major issuer domains were checked against current public sources on 28 October 2026. Other links are directories and must be rechecked before applying.','Source-first research')}<div class="notice warn"><strong>Verify website identity and current URL.</strong> Follow official government cross-links if a domain has moved. These links do not indicate a current vacancy, active application or live verification.</div><div class="panel source-tools"><label for="source-search">Find an organization</label><input id="source-search" type="search" placeholder="Search SSC, UPSC, railway, banking..." autocomplete="off"><label for="source-category">Category</label><select id="source-category"><option value="">All categories</option>${[...new Set(sources.map(s=>s.category))].sort().map(v=>`<option value="${h(v)}">${h(v)}</option>`).join('')}</select><p id="source-count" class="muted tiny" role="status">${sources.length} source references</p></div><div class="grid" id="source-results">${sources.map(sourceCard).join('')}</div><section class="section"><h2>How to verify a job notification</h2><div class="panel content-block"><ol><li>Open the recruiting organization's website through a trustworthy government or institutional directory.</li><li>Find the recruitment advertisement and original notification PDF.</li><li>Check the notice number, publication date, eligibility, exact deadlines and correction updates.</li><li>Use only the application portal named by the official notice.</li><li>Recheck any corrigendum before paying permitted official fees or submitting documents.</li></ol><p class="muted tiny">This website does not receive application payments or collect candidate identity documents.</p></div></section><section class="section"><div class="panel content-block"><h2>What counts as a checked vacancy?</h2><p>Before adding a job to JobPath India, an editor must read the actual official advertisement, confirm its issuing organization, notice number, eligibility and dates, and inspect corrections. Each genuine listing must provide an original notification link and a last-checked date.</p><p>CWC, RRB and NIICL recruitment records were source checked on 28 October 2026. Other source links are directory references and do not imply an open vacancy.</p></div></section>`}

const GUIDE_CONTENT={
 careers:{title:'Government Recruitment Pathways',sub:'A decision guide for identifying the correct recruiter, examination and source—not a list of advertised openings.',rows:[['SSC and Central Government','SSC commonly conducts central recruitment examinations. Compare advertisements, eligibility and exam stages on the commission site.','/ssc-recruitment/'],['UPSC examination pathways','Civil services and other UPSC examinations have distinct notices, calendars and qualifications.','/upsc-recruitment/'],['Railway recruitment regions','Different Railway Recruitment Boards and Cells handle specific notifications. Match the advertised board and region.','/railway-jobs/'],['Banking recruitment','IBPS and bank-specific career sites may publish different recruitment processes. Check each individual employer.','/banking-jobs/'],['AP and Telangana state recruitment','State commissions and departmental boards issue separate notifications and exam calendars.','/states-directory/'],['Teaching eligibility versus hiring','CTET and similar tests are eligibility assessments; they do not automatically constitute job openings.','/teaching-jobs/'],['Police and Defence','Verify physical, medical, education, and age criteria from each specific notice.','/police-defence-jobs/']]},
 application:{title:'How to Apply for Government Jobs Safely',sub:'A practical application workflow that avoids third-party payment traps and deadline mistakes.',rows:[['1. Locate the actual issuer','Begin at a known organization website and confirm that the recruitment body and its domain belong to the issuing agency.','/official-sources/'],['2. Download the exact advertisement','Match the notice ID, job title, publication date, recruitment year, and issuing organization.','/verify-notice/'],['3. Check eligibility carefully','Read educational requirements, age reference date, relaxations, nationality, language rules, and experience.','/qualification-wise-jobs/'],['4. Track dates and corrections','Record opening and closing times, fee payment deadlines, correction windows and revised exam schedules.','/important-dates/'],['5. Apply only on the linked official portal','Do not upload identity documents or pay fees on unrelated sites. Keep payment receipts and acknowledgement IDs.','/official-sources/'],['6. Prepare for the next stage','Save the submitted form; monitor admit-card, examination date, answer-key, result and document verification notices.','/exam-calendar/']]},
 editorial:{title:'Editorial & Correction Policy',sub:'Our criteria for publishing factual recruitment summaries and correcting information promptly.',rows:[['Verification gate','No vacancy is labeled verified until an editor checks the official notification URL and application destination, advertisement ID, eligibility and dates.','/verify-notice/'],['Date and status handling','A passed application deadline changes the displayed status to closed. An examination-date update never creates a job vacancy.','/important-dates/'],['Corrections and superseded notices','Track corrigenda and amendment dates, record what changed, and mark records requiring re-verification.','/recruitment-updates/'],['Source transparency','Show the issuing authority, published date, exact source links and last verified date; missing data stays unspecified.','/official-sources/'],['Advertising separation','Ads must be labeled, clearly separated from application buttons and never presented as official form links.','/privacy-policy/'],['Non-affiliation and privacy','We are an independent information service and do not take recruitment fees or collect candidate identity documents.','/disclaimer/']]},
 faq:{title:'Frequently Asked Questions',sub:'Helpful answers to common questions about recruiting authorities, exam notices and using this portal.',rows:[['Is JobPath India a government website?','No. It is independent and not affiliated with any central or state recruitment body.','/disclaimer/'],['Are the jobs on this site currently open?','Only separately checked vacancies would appear as real listings. At present there are no independently verified vacancies published.','/latest-jobs/'],['Where should I apply?','Use only the application link published by the actual recruiting authority in its current notice.','/official-sources/'],['What does a corrigendum mean?','It is a correction or amendment to an earlier notice. Recheck it before relying on previous dates.','/exam-updates/'],['Can I receive SMS or email alerts here?','No. Only local saved-job bookmarks work in the current static version; no push or email delivery is implemented.','/job-alerts/'],['Does submitting a sitemap guarantee Google indexing?','No. Sitemap submission helps discovery but Google decides when and whether to index a page.','/editorial-policy/'],['Why are some URLs missing?','An uncertain official domain is not invented. Use an authoritative government directory to confirm the current destination.','/official-sources/']]},
 maintenance:{title:'Editorial Maintenance & 30-Day Plan',sub:'A repeatable 30-day workflow for improving trust, usefulness, SEO and data quality without paid services.',rows:[['Days 1–5 · Source register','Confirm organization identity and current official domains. Record the date each official URL was checked.','/official-sources/'],['Days 6–10 · Notice verification','Review specific original PDF notices, corrigenda, real application windows and exact links before adding any vacancy.','/verify-notice/'],['Days 11–15 · Exam information','Publish carefully attributed exam calendars, notice changes, admit-card guidance and syllabus explanations.','/exam-calendar/'],['Days 16–20 · Regional coverage','Expand AP, Telangana and other state pathways with first-party sources rather than copied listings.','/states-directory/'],['Days 21–25 · Quality and accessibility','Review dead links, mobile layout, keyboards, contrast, readable labels and expired record status.','/editorial-policy/'],['Days 26–30 · Search and analytics','Review Search Console page indexing and crawl issues, update accurate internal links, and refine helpful original content.','/faq/']]},
 verify:{title:'How to Verify an Official Recruitment Notice',sub:'A source-first verification checklist for avoiding fake job advertisements and old application links.',rows:[['Issuer identity','Find the notice from the recruiting organization homepage. A forwarded PDF image alone is not independent verification.','/official-sources/'],['Advertisement ID and year','Match the advertisement number, department, position, recruitment cycle and PDF publication date.','/application-guide/'],['Eligibility and fees','Check qualifications, age limits, category relaxations, experience and official payment instructions.','/qualification-wise-jobs/'],['Application and final date','Use the date and time in the official notice, including amendments and extension notifications.','/important-dates/'],['Exam dates and corrections','Treat words like proposed, tentative, revised and final as different statuses.','/exam-updates/'],['Evidence record','Store a source URL, checked-on date, factual excerpt, publisher and the later correction history.','/editorial-policy/']]}
};
function guidePage(kind){const info=GUIDE_CONTENT[kind];return `${intro(info.title,info.sub,'Practical research guide')}<div class="guide-stack">${info.rows.map(([title,body,url],i)=>`<article class="panel guide-step"><span class="step-count">${String(i+1).padStart(2,'0')}</span><div><h2>${h(title)}</h2><p>${h(body)}</p><a href="${url}">Explore related information →</a></div></article>`).join('')}</div><section class="section">${ad()}</section>`}
function allStatesPage(){const draw=(names,head)=>`<section class="section"><h2>${h(head)} <span class="muted tiny">${names.length} regions</span></h2><div class="region-grid">${names.map(n=>`<a class="region" href="/job-search/?state=${encodeURIComponent(n)}"><span>📍 ${h(n)}</span><small>Browse verified jobs →</small></a>`).join('')}</div></section>`;return `${intro('Jobs by State & Union Territory','All 28 states and 8 union territories are listed for navigation. A region link is a search filter, not proof of an active notification.','All-India coverage')}<div class="notice warn">No current vacancy counts are inferred from this regional directory. Always cross-check a state commission or the issuing department.</div>${draw(regions.states,'28 Indian states')}${draw(regions.unionTerritories,'8 union territories')}<div class="section">${sourcesTeaser()}</div>`}
function calendarPage(){return `${intro('Government Exam Calendar','Different exam bodies publish and revise their own dates. This planning board separates confirmed personal reminders from unverified information.','Examination planning')}<div class="grid">${[['SSC & central exams','Visit the SSC website and compare date notices, corrigenda and application events.','/ssc-recruitment/'],['Civil services & UPSC','Verify the year-specific UPSC examination calendar and subsequent changes.','/upsc-recruitment/'],['Railway exams','Dates vary by recruitment board and advertisement number.','/railway-jobs/'],['Banking exam cycles','IBPS, SBI and individual banks publish their own schedules.','/banking-jobs/'],['State examination calendars','Check APPSC, Telangana commission and individual state departments.','/states-directory/'],['Admit cards & results','Treat candidate login notices and result notices separately from the exam date.','/admit-cards/']].map(([a,b,url])=>tile(['🗓️',a,url,b])).join('')}</div>${examTeaser()}<section class="section"><h2>Personal planning checklist</h2><div class="panel content-block"><ol><li>Write the official notification name, number, authority and current source URL.</li><li>Record application start, last date/time and any correction window.</li><li>Mark exam date as proposed/tentative or final according to the notice wording.</li><li>Recheck authority notices before booking travel or paying fees.</li><li>Track admit cards, answer keys, results and later document verification separately.</li></ol></div></section>`}

function apNoticeBoard(){
 const cards=noticeWatch.map(n=>`<article class="source-card"><div class="tags"><span class="tag demo">NOTICE · DATES NOT VERIFIED</span></div><h3>${h(n.title)}</h3><p><strong>APPSC notification:</strong> ${h(n.noticeNumber)} · ${h(n.publishedDate)}</p><p class="muted tiny">${h(n.status)} · Last source check ${h(n.lastChecked)}</p><a href="${h(safeUrl(n.sourceUrl)||'/official-sources/')}" target="_blank" rel="noopener noreferrer">Open APPSC notification register ↗</a></article>`).join('');
 return `<section class="section"><h2>APPSC 2026 notification watch</h2><p>These titles and notice numbers appear in the official APPSC register. They are <strong>not</strong> marked open because detailed deadlines and eligibility were not independently checked. Always open the newest notification and corrigenda.</p><div class="grid">${cards||'<p>No notice summaries available.</p>'}</div></section>`;
}

function updatesHub(){return `${intro('Recruitment & Examination Updates','Source-labeled notices and exam-schedule changes. A corrigendum is not itself a fresh job opening.','Notice desk')}${apNoticeBoard()}${autoNoticesSection(12)}${examTeaser()}<div class="panel content-block"><h2>How updates are reviewed</h2><p>We compare the issuer, reference number, notice date, wording, revised information and later corrigenda. The supplied October 2026 SSC screenshot has not been independently checked against a direct official PDF, so it is clearly marked pending verification.</p><a href="/editorial-policy/">Read verification policy →</a></div>`}

function articles(page){const sections={
 admit:['Government Exam Admit Cards','Always download an admit card from the official examination/candidate login, not an unknown third-party download link.',[['Before downloading','Check the recruiting organization, advertised notice number, examination city/date notice, and official candidate sign-in instructions.'],['After downloading','Verify your name, roll number, photograph, reporting time, exam location and ID requirements; contact the authority if anything differs.'],['Current admit cards','No admit-card availability is verified on this website. Use the official source directory to locate the examination authority.']]],
 results:['Government Exam Results','Result announcements, marks and merit lists must be checked against the recruiting authority.',[['Verify the result','Confirm the exam name, year, notice number and whether the PDF is a provisional list, marksheet or final selection.'],['Next steps','Save the official result notice, check cutoff or verification schedules, and follow instructions issued by the recruiting organization.'],['Current results','No current result release has been independently verified for this build.']]],
 syllabus:['Government Exam Syllabus','A reliable syllabus comes from an official exam advertisement or a current syllabus PDF published by the responsible organization.',[['Find the right version','Match the syllabus year and advertisement number. Use the exam pattern and paper-wise topics listed by the authority.'],['Prepare effectively','Build a revision plan around the official sections, practice with past papers where allowed, and review changes before exams.'],['Syllabus documents','No unofficial PDF downloads or outdated syllabus are represented as current here.']]],
 upcoming:['Upcoming Government Exams','A planning hub for examination pathways. Dates must come from the latest official examination calendar.',[['Build a calendar','Track notices, application windows, admit cards, exam dates and result announcements separately.'],['Monitor changes','Look for official rescheduling and corrigendum notices. Avoid treating a coaching-site schedule as final.'],['Current calendar','Live upcoming examination dates have not been verified for publication yet.']]],
 alerts:['Job Alerts & Saved Preferences','Bookmarks are functional locally. Email, SMS, browser push and daily automatic alerts are not implemented in this release.',[['What works now','Save fictional job examples with the heart button, review them under Saved Jobs, and retain them while browser storage is available.'],['What does not work yet','No user accounts, background notifications, newsletter emails or server-side alert system. This site cannot notify you when a real notification appears.'],['Future upgrades','A verified-notice editorial workflow, opt-in alerts, and an auditable notification schedule can be added when a backend and consent handling are available.']]],
 about:['About JobPath India','JobPath India is a new, independent project designed to make government recruitment information easier to explore.',[['Our mission','Improve navigation, demonstrate useful search filters, and help readers identify the true recruitment source without fabricated vacancy claims.'],['Our standards','Show the source and verification date before publishing any genuine listing. Mark unverified information clearly and close expired advertisements.'],['Our independence','We are not operated, sponsored, affiliated with or endorsed by any Government of India or state government department.']]],
 contact:['Contact & Corrections','We take factual errors, outdated links and potential recruitment misinformation seriously.',[['Contact status','A verified public support email address has not been configured. We have intentionally not included a nonfunctional contact form or exposed a private personal email.'],['For application questions','Contact the recruiting organization through the communication channels in its official notification. JobPath India does not process applications.'],['For website corrections','A public reporting channel can be added when the owner chooses a dedicated project address. Until then, please do not submit personal documents or sensitive data.']]],
 privacy:['Privacy Policy','This policy describes the current static version of JobPath India.',[['Information stored locally','We use browser localStorage for theme preference and saved example job IDs. These values stay in your browser and may disappear when browsing data is cleared.'],['Server and hosting logs','Netlify may process standard request metadata and technical logs to serve the website under its own policies. We do not operate a visitor-account database in this static release.'],['Third-party links','External organization links lead to third-party sites with their own policies. We do not control those sites.'],['Google Analytics 4','Optional analytics is loaded only after you click Allow analytics. If enabled, Google Analytics measures visits, page views, traffic sources and engagement. Google may process cookies, IP addresses and browser/device data under its own privacy terms. You can refuse without losing access to the site.'],['Advertising',adSenseReady(adsConfig)?'Approved advertising may be served by Google AdSense, which can process cookies and device or advertising identifiers subject to applicable consent and privacy rules. See Google’s advertising privacy information and your browser privacy controls. Ads are labeled and separate from official recruitment links.':'No active ads or advertising tracking code are installed in this build. If Google AdSense is enabled after approval, third-party advertising technologies, privacy notices and applicable consent handling must be reviewed before serving personalized ads.'],['Your choices','Use Analytics choices in the footer to change optional analytics permissions at any time. Declining after previously allowing stops new tracking after the page reloads; you may also clear cookies and browser storage to remove saved preferences.']]],
 terms:['Terms and Conditions','Use this site as independent general information, not as official recruitment instructions.',[['Accuracy','Any real notice must be checked against the latest official source. Sample entries are not real opportunities.'],['No agency relationship','This website is not affiliated with public recruitment agencies and does not guarantee selection, employment or examination results.'],['Safe usage','Do not submit sensitive identity documents or payment details to this portal. Follow official application instructions only.'],['Availability','Features and source references may change. External websites are controlled by their respective owners.']]],
 disclaimer:['Independent Website Disclaimer','JobPath India is not an official Government of India website and is not affiliated with any recruitment authority.',[['Verified and demo records','Source-checked recruitment entries are published alongside an optional, explicitly labeled training dataset. Fictional examples are hidden from public search by default and are not real opportunities.'],['Not official instructions','Official recruitment notifications, application rules, fee schedules, corrections and deadlines are controlled solely by the relevant recruiting authority.'],['Source verification','Major recruiting organizations are cross-checked against official sources where available, while some directory entries remain untested. Always verify the final URL with the issuer.'],['No payments or hiring','We do not collect recruitment fees, receive applications, offer jobs, issue admit cards or publish examination results on behalf of any authority.']]],
 };const [title,desc,blocks]=sections[page];return `${intro(title,desc,'Helpful guide')}<article class="panel content-block">${blocks.map(([name,body])=>`<section><h2>${h(name)}</h2><p>${h(body)}</p></section>`).join('')}<div class="action-row"><a class="btn btn-secondary" href="/official-sources/">Official sources ↗</a><a class="btn btn-secondary" href="/job-search/">Try search</a></div></article>`}
function adsterraPrivacyPage(){
 const status=adsterraReady(adsConfig)?'Optional Adsterra native advertising is available. No advertising script is requested until you choose Allow advertising.':'Adsterra advertising has been prepared but is currently disabled. No third-party advertising request is made while it is disabled.';
 return `${intro('Privacy Policy','Updated 29 October 2026. Your advertising choice is optional.','Privacy and advertising')}
 <article class="panel content-block">
 <section><h2>Browser storage</h2><p>Theme preferences and saved job identifiers are stored in this browser. When advertising is available, your allow/decline choice and its timestamp are also stored locally for up to 180 days. Clearing site storage removes these preferences.</p></section>
 <section><h2>Hosting and official links</h2><p>Netlify may process request metadata and technical logs to deliver this website under its own policies. External recruiting organizations operate their own websites and privacy practices. This portal does not collect applications, identity documents or recruitment payments.</p></section>
 <section><h2>Optional advertising</h2><p>${h(status)}</p><p>If you allow advertising, Adsterra and its advertising partners may process cookies or similar identifiers, IP address, browser/device information and advertising interactions to deliver, measure and personalize ads. Third parties may process this information in other countries under their own policies.</p><p><a href="https://adsterra.com/privacy-policy-managed/" target="_blank" rel="noopener noreferrer">Read Adsterra’s privacy policy</a> and <a href="https://adsterra.com/cookies/" target="_blank" rel="noopener noreferrer">cookies policy</a> for further information and privacy-contact details.</p></section>
 <section><h2>Your choices</h2><p>You can continue using all recruitment information without advertising. When ads are available, use Continue without ads to decline, or Advertising choices in the footer to change or withdraw your choice. Withdrawing after ads have loaded refreshes the page to stop the active advertising script. We respect the Global Privacy Control signal by keeping these ads off. Browser controls can remove third-party cookies already stored by an advertising provider.</p>${adsterraReady(adsConfig)?'<button type="button" class="btn btn-secondary" data-ad-choices>Advertising choices</button>':''}</section>
 <section><h2>Independent recruitment information</h2><p>Advertisements are labeled and are separate from official recruitment links. An advertisement is not a government notice or an application instruction. Advertising never unlocks or pays for access to this portal.</p></section>
 </article>`;
}

function renderMain(){if(PAGE==='privacy'&&adsterraConfigured(adsConfig))return adsterraPrivacyPage();if(PAGE==='autonotices')return autoNoticesPage();if(PAGE==='examupdates')return examUpdatesPage();if(PAGE==='statesdir')return allStatesPage();if(PAGE==='calendar')return calendarPage();if(PAGE==='careerguides')return guidePage('careers');if(PAGE==='applicationguide')return guidePage('application');if(PAGE==='editorial')return guidePage('editorial');if(PAGE==='faq')return guidePage('faq');if(PAGE==='maintenance')return guidePage('maintenance');if(PAGE==='contactsources')return guidePage('verify');if(PAGE==='updates')return updatesHub();if(PAGE==='upcoming')return articles(PAGE)+examTeaser();if(PAGE==='ssc')return listing(PAGE)+examTeaser();if(PAGE==='home')return home();if(PAGE==='ap')return listing(PAGE)+apNoticeBoard();if(CATS[PAGE])return listing(PAGE);if(PAGE==='job')return detail();if(PAGE==='saved')return savedPage();if(PAGE==='dates')return deadlinePage();if(PAGE==='qualifications')return qualificationPage();if(PAGE==='sources')return officialSources();return articles(PAGE)}
function updateSavedButtons(){document.querySelectorAll('[data-save]').forEach(btn=>{const yes=saved.has(btn.dataset.save);btn.textContent=yes?'♥ Saved':'♡ Save';btn.setAttribute('aria-pressed',String(yes))});const counter=document.getElementById('saved-count');if(counter)counter.textContent=saved.size}
function attach(){document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){const nav=document.getElementById('primary-nav'),button=document.querySelector('[data-menu]');if(nav?.classList.contains('open')){nav.classList.remove('open');button?.setAttribute('aria-expanded','false');button?.setAttribute('aria-label','Open navigation menu');if(button){button.textContent='☰';button.focus()}}}});document.addEventListener('click',async ev=>{const target=ev.target.closest('button');if(!target)return;
 if(target.hasAttribute('data-ad-choices'))openAdvertisingChoices(adsConfig);
 if(target.hasAttribute('data-ad-choices-close'))closeAdvertisingChoices();
 if(target.hasAttribute('data-ad-choice')){if(!chooseAdvertising(adsConfig,target.dataset.adChoice))toast('Your advertising choice could not be saved. Check your browser privacy settings.');return;}
 if(target.hasAttribute('data-theme-toggle')){setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark')}
 if(target.hasAttribute('data-menu')){const nav=document.getElementById('primary-nav');const open=nav.classList.toggle('open');target.setAttribute('aria-expanded',String(open));target.setAttribute('aria-label',open?'Close navigation menu':'Open navigation menu');target.textContent=open?'✕':'☰'}
 if(target.hasAttribute('data-save')){const id=target.dataset.save;if(saved.has(id))saved.delete(id);else saved.add(id);remember();if(PAGE==='saved'){document.querySelector('main .wrap').innerHTML=renderMain()}else updateSavedButtons();toast(saved.has(id)?'Saved in this browser':'Removed from saved jobs')}
 if(target.hasAttribute('data-copy-link')){try{await navigator.clipboard.writeText(location.href);toast('Link copied')}catch{toast('Clipboard unavailable. Use the address bar to copy.') }}
 if(target.hasAttribute('data-share')){if(navigator.share){try{await navigator.share({title:document.title,url:location.href})}catch{}}else{try{await navigator.clipboard.writeText(location.href);toast('Share link copied')}catch{toast('Copy the URL from the address bar to share')}}}
 if(target.hasAttribute('data-print'))window.print();
 if(target.hasAttribute('data-clear-filters')){const form=document.getElementById('search-form');form.reset();form.querySelectorAll('input,select').forEach(el=>el.value='');const sort=document.getElementById('filter-sort');if(sort)sort.value='newest';renderResults();toast('All filters cleared')}
 });
 const sourceSearch=document.getElementById('source-search'),sourceCategory=document.getElementById('source-category');if(sourceSearch&&sourceCategory){const filterSources=()=>{let count=0;const name=sourceSearch.value.trim().toLowerCase(),cat=sourceCategory.value;document.querySelectorAll('#source-results .source-card').forEach(card=>{const match=(!name||card.dataset.sourceName.includes(name))&&(!cat||card.dataset.sourceCategory===cat);card.hidden=!match;if(match)count++});document.getElementById('source-count').textContent=`${count} organization reference${count===1?'':'s'} found`};sourceSearch.addEventListener('input',filterSources);sourceCategory.addEventListener('change',filterSources)}
 const form=document.getElementById('search-form');if(form){form.addEventListener('submit',ev=>ev.preventDefault());let timer;form.addEventListener('input',ev=>{if(ev.target.name==='q'){clearTimeout(timer);timer=setTimeout(renderResults,130)}else renderResults()});form.addEventListener('change',renderResults);document.getElementById('filter-sort')?.addEventListener('change',renderResults);renderResults()}
}
// Source-backed fallback ensures a transient or cached JSON request cannot blank the entire site.
// This screenshot-based corrigendum is labeled unverified, not an official vacancy notice.
const BUILTIN_EXAM_UPDATES=[{"id":"ssc-2026-corrigendum-exam-dates","type":"Exam date corrigendum — not a new vacancy","title":"SSC 2026: Revised proposed dates for JE Paper-I and SI (Delhi Police/CAPFs)","organization":"Staff Selection Commission (SSC)","reference":"HQ-EC033/7/2025-EC","noticeHeading":"Corrigendum to Important Notice dated 01.10.2026","noticeSignedDate":"2026-10-26","referencedNoticeDate":"2026-10-01","source":"User-supplied images of a document bearing the SSC heading","sourceStatus":"Not independently verified against an official live notice/PDF","officialWebsite":"https://ssc.gov.in/","directOfficialNoticeUrl":null,"recruitmentApplicationOpen":false,"applicationDeadline":null,"vacancyCount":null,"revisedProposedExams":[{"name":"Junior Engineer Examination, 2026","tier":"Paper-I (CBE)","windows":[{"start":"2026-11-02","end":"2026-11-06"},{"start":"2026-11-30","end":"2026-12-01"}]},{"name":"Sub-Inspector in Delhi Police and Central Armed Police Forces Examination, 2026","tier":"CBE","windows":[{"start":"2026-11-23","end":"2026-11-28"}]}],"caveat":"Dates are revised proposed dates in the supplied corrigendum. Visit SSC regularly for additional changes and confirm the most recent official notice.","imageFiles":["/assets/notices/ssc-2026-corrigendum-page-1.png","/assets/notices/ssc-2026-corrigendum-page-2.png"]}];
async function readData(path,fallback,isValid){
 try{const tag=document.getElementById('jobpath-data');if(tag){const bundled=JSON.parse(tag.textContent);const value=bundled[path];if(isValid(value))return value;}
 const r=await fetch(path,{cache:'no-store'});if(!r.ok)throw new Error(`HTTP ${r.status}`);
 const parsed=await r.json();if(!isValid(parsed))throw new Error('Unexpected JSON format');return parsed;
 }catch(err){console.warn(`Data unavailable: ${path}; using safe fallback.`,err.message);return fallback;}
}
async function init(){
 try{
 [jobs,sources,pages,examUpdatesData,regions,noticeWatch,autoNotices,adsConfig]=await Promise.all([
 readData('/data/jobs.json',[],Array.isArray),
 readData('/data/sources.json',[],Array.isArray),
 readData('/data/pages.json',{},x=>x!==null&&typeof x==='object'&&!Array.isArray(x)),
 readData('/data/exam-updates.json',BUILTIN_EXAM_UPDATES,Array.isArray),
 readData('/data/regions.json',{states:[],unionTerritories:[]},x=>x&&Array.isArray(x.states)&&Array.isArray(x.unionTerritories)),
 readData('/data/notice-watch.json',[],Array.isArray),
 readData('/data/auto-notices.json',{version:1,notices:[]},x=>x&&x.version===1&&Array.isArray(x.notices)),
 readData('/data/ads-config.json',{enabled:false,provider:'none',publisherId:'',slots:{content:''}},x=>x&&typeof x.enabled==='boolean'&&typeof x.provider==='string')
 ]);
 adsConfig=resolveAdvertisingConfig(adsConfig,globalThis.window?.location?.hostname||globalThis.location?.hostname||'');
 // Even if all network JSON reads fail, the site shell and verified-by-document transcription remain visible.
 if(!examUpdatesData.length)examUpdatesData=BUILTIN_EXAM_UPDATES;
 app.innerHTML=header()+(PAGE==="home"?"":topAd())+`<main id="main" tabindex="-1"><div class="wrap">${renderMain()}</div></main>`+footer();
 if(advertisingReady(adsConfig)){startAdUnits(adsConfig);monitorBannerFill();}
 try{setTheme(localStorage.getItem('jp_theme')==='dark'?'dark':'light')}catch{setTheme('light')}
 attach();
 }catch(err){console.error('Website display failed',err);
 // Keep the accessible static HTML present in the original page instead of replacing it with a generic error.
 if(!app.querySelector('main'))app.innerHTML=`<main id="main"><div class="wrap"><section class="page-intro"><h1>Page temporarily unavailable</h1><p>Please reload this page.</p><a href="/" class="btn btn-primary">Back to homepage</a></section></div></main>`;
 }
}
init();
